style.css:
@-moz-document domain("smashkarts.io") {
/* --- RTX GLOBAL INJECTOR --- */
    html {
        filter: saturate(1.4) contrast(1.1) hue-rotate(-2deg) !important;
        height: 100%;
        background-color: #050505 !important;
    }

    * {
        transform-style: preserve-3d;
        box-sizing: border-box !important;
        text-shadow: 0 2px 4px rgba(0, 0, 0, 0.8), 0 0 15px rgba(255, 255, 255, 0.1) !important;
        -webkit-font-smoothing: antialiased;
    }

    /* 3. THE "GAME WINDOW" RENDER ENGINE */
    canvas,
    video {
        /* RT Shadow Stack */
        box-shadow: 
            0 0 60px rgba(0, 0, 0, 0.9),
            0 0 25px var(--primary-color, #00f0ff) !important;
        
        border-radius: 12px !important;
        border: 1px solid rgba(255, 255, 255, 0.15) !important;

        /* 
           RTX SHARPEN ENGINE:
           1. url(): Inline SVG Convolution Matrix (Sharpening kernel)
           2. contrast: Higher contrast (1.1) works better with sharpening
           3. blur: Reduced to 0.2px to act as light FXAA after the sharpen pass
        */
        filter: 
            url("data:image/svg+xml;utf8,<svg xmlns='www.w3.org'><filter id='sharpen'><feConvolveMatrix order='3' preserveAlpha='true' kernelMatrix='0 -1 0 -1 5 -1 0 -1 0'/></filter></svg>#sharpen")
            contrast(1.2) 
            saturate(1.2) 
            blur(0.2px) 
            brightness(0.9) !important;

        /* Ensures high-fidelity edge scaling for 2025 browsers */
        image-rendering: -webkit-optimize-contrast !important;
        image-rendering: crisp-edges !important;
        
        transition: filter 0.3s ease;
    }

    /* 4. UI PANELS (Glassmorphism & Refraction) */
    div[class*="panel"], 
    div[class*="modal"],
    .hud-container {
        backdrop-filter: blur(8px) saturate(1.8) !important;
        background: rgba(0, 0, 0, 0.4) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
    }

    /* 5. INTERACTIVE OBJECTS (3D Geometry Buttons) */
    button,
    input,
    a[class*="btn"],
    [role="button"] {
        background: linear-gradient(145deg, rgba(255, 255, 255, 0.1), rgba(0, 0, 0, 0.4)) !important;
        border: 1px solid rgba(255, 255, 255, 0.2) !important;
        box-shadow: 
            5px 5px 15px rgba(0, 0, 0, 0.6),
            inset 1px 1px 2px rgba(255, 255, 255, 0.2) !important;
        transition: all 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important;
    }

    button:hover {
        transform: translateY(-3px) scale(1.03) !important;
        filter: brightness(1.2) saturate(1.4) !important;
        box-shadow: 0 0 30px rgba(0, 240, 255, 0.5) !important;
        border-color: #00f0ff !important;
    }

    /* 6. SCROLLBARS (Neon Energy) */
    ::-webkit-scrollbar { width: 8px; background: #0a0a0a; }
    ::-webkit-scrollbar-thumb {
        background: linear-gradient(180deg, #00f0ff, #7000ff);
        border-radius: 4px;
        box-shadow: 0 0 10px #00f0ff;
    }
}
